  page.goto(base);page.locator('#course-title-fr').fill('Première version');page.evaluate('window.__courseDelay=700');page.get_by_role('button',name='Enregistrer en brouillon',exact=False).first.click();page.wait_for_function('window.__courseSaved');page.locator('#course-title-fr').fill('Modification pendant enregistrement');page.get_by_text('Enregistrement confirmé. Vos nouvelles modifications restent dans le brouillon.',exact=True).wait_for();assert page.evaluate('(key)=>JSON.parse(localStorage.getItem(key)).data.titleFr',key)=='Modification pendant enregistrement';page.reload();page.locator('#course-title-fr').wait_for();assert page.locator('#course-title-fr').input_value()=='Modification pendant enregistrement'
