  browser=p.chromium.launch(headless=True);page=browser.new_page();page.add_init_script("const original=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){if(key.startsWith('faro:course-draft'))throw new DOMException('quota','QuotaExceededError');return original.call(this,key,value)}")
